#!/usr/bin/env bash
# generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
#
# Build the Nextcloud frontend bundle and verify it can run in a browser.
#
# Usage: bash scripts/build-frontend.sh
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(dirname "$SCRIPT_DIR")"
cd "$PROJECT_ROOT"

BUNDLE="js/upm.js"

echo "==> Building $BUNDLE"
npm run build

[ -f "$BUNDLE" ] || { echo "error: $BUNDLE was not produced" >&2; exit 1; }

# Vite lib mode leaves `process.env.NODE_ENV` for the consumer to define; the
# browser has no `process`, so such a bundle crashes on load. Bake it in via
# vite.config.ts and check the result.
if grep -q 'process\.env\.NODE_ENV' "$BUNDLE"; then
	echo "error: $BUNDLE still references process.env.NODE_ENV" >&2
	echo "       add it to the 'define' block in vite.config.ts" >&2
	exit 1
fi

# Other `process.*` uses must be guards like `typeof process === 'object'`.
# Report them so a regression is visible even if it only shows on load.
if remaining="$(grep -o 'process\.[A-Za-z_][A-Za-z0-9_.]*' "$BUNDLE" | sort -u)" && [ -n "$remaining" ]; then
	echo "note: guarded Node globals remain in the bundle:"
	echo "$remaining" | sed 's/^/      /'
fi

echo "==> OK: $(wc -c < "$BUNDLE") bytes, no unguarded process.env.NODE_ENV"
